<?php
namespace Tests\Feature;
use App\Models\Payment;use App\Models\Trip;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class WompiPaymentTest extends TestCase{use RefreshDatabase;
 private function payment():Payment{$u=User::factory()->create(['role'=>'pasajero','email_verified_at'=>now()]);$driver=User::factory()->create(['role'=>'conductor','email_verified_at'=>now()]);$t=Trip::create(['passenger_id'=>$u->id,'driver_id'=>$driver->id,'vehicle_type'=>'carro','department'=>'Putumayo','municipality'=>'Mocoa','origin'=>'A','destination'=>'B','origin_lat'=>1,'origin_lng'=>-76,'destination_lat'=>1.1,'destination_lng'=>-76.1,'status'=>'completed','estimated_cost'=>10000,'final_cost'=>10000]);return Payment::create(['trip_id'=>$t->id,'user_id'=>$u->id,'amount'=>10000,'currency'=>'COP','amount_in_cents'=>1000000,'status'=>'pending','provider'=>'wompi','provider_reference'=>'TRIP-TEST']);}
 private function payload(string $status='APPROVED',int $amount=1000000):array{$p=['event'=>'transaction.updated','data'=>['transaction'=>['id'=>'tx-1','status'=>$status,'amount_in_cents'=>$amount,'currency'=>'COP','reference'=>'TRIP-TEST','payment_method_type'=>'CARD']],'environment'=>'test','signature'=>['properties'=>['transaction.id','transaction.status','transaction.amount_in_cents'],'checksum'=>''],'timestamp'=>1700000000];$p['signature']['checksum']=hash('sha256','tx-1'.$status.$amount.'1700000000events_test');return $p;}
 protected function setUp():void{parent::setUp();config(['payments.wompi.events_secret'=>'events_test']);}
 public function test_signed_webhook_completes_payment_once():void{$payment=$this->payment();$payload=$this->payload();$this->postJson(route('webhooks.wompi'),$payload)->assertOk();$this->postJson(route('webhooks.wompi'),$payload)->assertOk();$this->assertSame('completed',$payment->fresh()->status);$this->assertSame('tx-1',$payment->fresh()->provider_transaction_id);$this->assertDatabaseCount('payment_webhook_events',1);}
 public function test_webhook_rejects_bad_signature_and_tampered_amount():void{$payment=$this->payment();$bad=$this->payload();$bad['signature']['checksum']='bad';$this->postJson(route('webhooks.wompi'),$bad)->assertUnauthorized();$tampered=$this->payload('APPROVED',999);$this->postJson(route('webhooks.wompi'),$tampered)->assertStatus(422);$this->assertSame('pending',$payment->fresh()->status);}
}